<script setup>
import StatusBadge from "./StatusBadge.vue";
const props = defineProps({ material: { type: Object, required: true }, admin: Boolean }); const emit = defineEmits(["request", "edit"]);
const icons = { Ordinateur: "💻", Écran: "🖥️", Imprimante: "🖨️", Accessoire: "⌨️", Téléphone: "📱", Réseau: "📡" }; const icon = () => icons[props.material.categorie] || "🧩"; const available = () => props.material.statut === "disponible" && props.material.quantite_disponible > 0;
</script>
<template><article class="card h-full border border-slate-100 bg-white shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div class="flex h-36 items-center justify-center rounded-t-2xl bg-gradient-to-br from-[#edf6ef] to-[#dcecdf] text-5xl">{{ icon() }}</div><div class="card-body gap-3 p-5"><div class="flex items-start justify-between gap-2"><div><p class="text-xs font-medium uppercase tracking-wide text-slate-400">{{ material.categorie }}</p><h3 class="font-semibold text-slate-800">{{ material.nom }}</h3></div><StatusBadge :status="available() ? 'disponible' : (material.statut === 'disponible' ? 'retire' : material.statut)" /></div><p class="line-clamp-2 min-h-10 text-sm text-slate-500">{{ material.description || 'Aucune description fournie.' }}</p><p class="text-sm text-slate-600"><strong class="text-[#17482d]">{{ material.quantite_disponible }}</strong> disponible{{ material.quantite_disponible > 1 ? 's' : '' }} / {{ material.quantite_totale }}</p><button v-if="admin" class="btn btn-outline btn-sm border-[#17482d] text-[#17482d]" @click="emit('edit', material)">Modifier</button><button v-else class="btn btn-sm border-0 bg-[#17482d] text-white hover:bg-[#0e3520]" :disabled="!available()" @click="emit('request', material)">{{ available() ? 'Demander' : 'Indisponible' }}</button></div></article></template>
